/// 把解析结果渲染成 `data_source_mixin.dart` / `repository.dart` 的文本。
///
/// 纯函数：不碰文件系统，模型文件的 import 列表由调用方算好传进来。
/// 输出与 `api.sh` 原产物保持一致（已格式化的形态），迁移期用 golden 比对。
library;

import 'client_parser.dart';

/// 生成物头部注释。
String renderHeader(String timestamp) {
  return [
    '// **************************************************************************',
    '// Auto-generated file. Do not edit manually.',
    '// **************************************************************************',
    '// This file was generated by api.sh on $timestamp',
    '// Changes will be overwritten the next time the script runs.',
    '// **************************************************************************',
  ].join('\n');
}

/// `data_source_mixin.dart`
String renderRemoteDataSource({
  required String header,
  required List<ApiMethod> methods,
  required Set<String> existingMethods,
  required List<String> modelFiles,
}) {
  final buffer = StringBuffer()
    ..writeln(header)
    ..writeln("import '../client.dart';")
    ..writeln();

  for (final file in modelFiles) {
    buffer.writeln("import '../../models/$file';");
  }
  if (modelFiles.isNotEmpty) {
    buffer.writeln();
  }

  buffer.writeln('abstract class IAppRemoteDataSource {');
  buffer.write(methods.map(_interfaceSignature).join('\n\n'));
  buffer.writeln();
  buffer.writeln('}');
  buffer.writeln();

  buffer.writeln('mixin AppRemoteDataSourceMixin implements IAppRemoteDataSource {');
  buffer.writeln('  late final ApiClient libRest;');

  for (final clientId in _customClientIds(methods)) {
    buffer.writeln('  late final ApiClient $clientId;');
  }

  final impls = <String>[];
  for (final method in methods) {
    if (existingMethods.contains(method.name)) {
      continue;
    }
    impls.add(_implementation(
      method,
      receiver: method.clientId ?? 'libRest',
    ));
  }

  if (impls.isNotEmpty) {
    buffer.writeln();
    buffer.write(impls.join('\n\n'));
    buffer.writeln();
  }

  buffer.writeln('}');

  return buffer.toString();
}

/// `repository.dart`
String renderRepository({
  required String header,
  required List<ApiMethod> methods,
  required List<String> modelFiles,
}) {
  final buffer = StringBuffer()
    ..writeln(header)
    ..writeln("import 'package:w_tools/w.dart';")
    ..writeln()
    ..writeln("import 'remote/data_source.dart';")
    ..writeln("import 'remote/data_source_mixin.dart';")
    ..writeln();

  for (final file in modelFiles) {
    buffer.writeln("import '../models/$file';");
  }
  if (modelFiles.isNotEmpty) {
    buffer.writeln();
  }

  buffer
    ..writeln('class AppRepository extends BaseRepository<Null, AppRemoteDataSource>')
    ..writeln('    implements IAppRemoteDataSource {')
    ..writeln('  AppRepository() : super(remoteDataSource: AppRemoteDataSource());')
    ..writeln()
    ..writeln('  static AppRepository? _instance;')
    ..writeln()
    ..writeln('  static AppRepository _getInstance() {')
    ..writeln('    _instance ??= AppRepository();')
    ..writeln('    return _instance!;')
    ..writeln('  }')
    ..writeln()
    ..writeln('  static AppRepository get instance => _getInstance();')
    ..writeln()
    ..writeln('  static bool destroyInstance() {')
    ..writeln('    if (_instance == null) {')
    ..writeln('      return false;')
    ..writeln('    }')
    ..writeln('    _instance = null;')
    ..writeln('    return true;')
    ..writeln('  }');

  if (methods.isNotEmpty) {
    buffer
      ..writeln()
      ..write(methods
          .map((method) => _implementation(method, receiver: 'remoteDataSource!'))
          .join('\n\n'))
      ..writeln();
  }

  buffer.writeln('}');

  return buffer.toString();
}

String _interfaceSignature(ApiMethod method) {
  return '  Future<${method.returnType}> ${method.name}(${_paramList(method.params)});';
}

String _implementation(ApiMethod method, {required String receiver}) {
  final args = method.params.map((param) => param.name).join(', ');
  return [
    '  @override',
    '  Future<${method.returnType}> ${method.name}(${_paramList(method.params)}) {',
    '    return $receiver.${method.name}($args);',
    '  }',
  ].join('\n');
}

String _paramList(List<ApiParam> params) {
  return params.map((param) => '${param.type} ${param.name}').join(', ');
}

List<String> _customClientIds(List<ApiMethod> methods) {
  final ids = <String>[];
  for (final method in methods) {
    final id = method.clientId;
    if (id != null && id.isNotEmpty && !ids.contains(id)) {
      ids.add(id);
    }
  }
  return ids;
}
